// stock_items is a real table (snake_case columns); everywhere else in the
// app works with items as camelCase JS objects, exactly as it always has —
// these are the only two places that need to know the table's column
// names at all. The third element is the column's real type, so a missing
// field gets the correct default (0 / false / "") rather than guessing
// from a value that's already absent.
const ITEM_DB_FIELDS = [
  ["mainCat", "main_cat", "text"],
  // Where this part is made, remembered so the next job with it comes in
  // tagged. One of MADE_ON_OPTIONS or blank. Needs setup-made-on-tag.sql
  // on the database first, or saving any stock item fails.
  ["madeOn", "made_on", "text"], ["loc", "loc", "text"], ["low", "low", "num"], ["salesPerson", "sales_person", "text"],
  ["customer", "customer", "text"], ["supplier", "supplier", "text"], ["grade", "grade", "text"], ["size", "size", "text"],
  ["thickness", "thickness", "text"], ["name", "name", "text"], ["sheetName", "sheet_name", "text"], ["stockType", "stock_type", "text"],
  ["comment", "comment", "text"], ["unit", "unit", "text"], ["trackLength", "track_length", "bool"], ["length", "length", "num"],
  ["qty", "qty", "num"], ["diameter", "diameter", "text"], ["partNumber", "part_number", "text"], ["manufacturer", "manufacturer", "text"],
  ["serialNumber", "serial_number", "text"], ["purchaseDate", "purchase_date", "text"], ["value", "value", "num"],
  // value is what a buy-out costs us. Stock is valued on it and a purchase
  // order prices itself from it.
  //
  // sell_price is still on the table and still mapped, but nothing on any
  // screen writes it: the selling price is being done separately. Kept so
  // that work starts from a screen rather than from a migration, and so
  // anything already stored is not thrown away.
  ["sellPrice", "sell_price", "num"],
  ["serviceMode", "service_mode", "text"], ["serviceIntervalMonths", "service_interval_months", "num"],
  ["serviceIntervalHours", "service_interval_hours", "num"], ["serviceIntervalKm", "service_interval_km", "num"],
  ["lastServiceDate", "last_service_date", "text"], ["lastServiceReading", "last_service_reading", "num"],
  ["currentReading", "current_reading", "num"], ["status", "status", "text"], ["fastenerType", "fastener_type", "text"],
  ["fastenerGrade", "fastener_grade", "text"], ["finish", "finish", "text"], ["attachmentType", "attachment_type", "text"],
  ["attachmentName", "attachment_name", "text"], ["storesKind", "stores_kind", "text"],
];
function dbRowToItem(row) {
  const item = { id: row.id };
  for (const [jsKey, dbKey] of ITEM_DB_FIELDS) item[jsKey] = row[dbKey];
  return item;
}
function itemToDbRow(item) {
  const row = { id: item.id };
  for (const [jsKey, dbKey, type] of ITEM_DB_FIELDS) {
    const v = item[jsKey];
    const fallback = type === "num" ? 0 : type === "bool" ? false : "";
    row[dbKey] = v === undefined || v === null ? fallback : v;
  }
  return row;
}

const MASTER_STRING_LISTS = [
  "sizes", "sectionTypes", "salesPeople", "customers", "staffDepartments", "jobProcessTypes",
  "storeCategories", "fastenerCategories", "fastenerGrades", "fastenerFinishes", "sheetNames",
  "laserMaterials",
  "laserThicknesses",
];
// Lists where the order on screen is the order that matters, not just how
// they happen to be stored. Job Process Types is the factory flow: the
// floor can't start a process until everything before it is complete, so
// its sequence is real production instruction, not presentation. These get
// reorder controls in the manager, and their positions are written back to
// sort_order. Every other list keeps its existing add-to-the-end
// behaviour, which also avoids rewriting hundreds of rows on lists like
// customers every time one is added.
//
// Laser Thicknesses is ordered for a different reason: it sets how the
// cut list groups programs at the machine. Left alphabetical, 10mm
// would sort next to 1.2mm, so the order has to be the shop's, not the
// alphabet's.
const ORDERED_STRING_LISTS = ["jobProcessTypes", "laserThicknesses"];

// Which department a shortage goes to was decided by comparing the process
// name against the exact strings "Nesting" and "Laser Operator". Process
// types are free text that each shop types in for itself, so anything else
// -- "nesting", "Tube Laser Operator", "Laser - External" -- failed the
// comparison, and the shortage was saved and then shown to nobody. It
// looked like shortages did not work; in fact they were invisible.
//
// Matching on the recognisable part of the name instead means a shortage
// reaches the right people whatever the shop calls the stage.
const isNestingProcess = (name) => /nest/i.test(name || "");
// The plate laser's own nesting. "Tube Laser Nesting" has the word in it
// too, but it is a different machine with a different flow -- named
// nestings and per-item quantities rather than program numbers -- so the
// Laser 4kw screens have to leave it alone. Shortage routing and the
// nesting document still use the broad match above, because both apply
// to tube nesting as much as plate.
const isPlateNestingProcess = (name) => /nest/i.test(name || "") && !/tube/i.test(name || "");
const isLaserProcess = (name) => /laser/i.test(name || "");
// The stage that SigmaNest programs actually cut. "Laser" but not "Tube
// Laser" and not "Laser - External": all three have the word in them, but
// they are different machines and only one of them runs off these
// programs. Tube laser gets its own nesting later, and when it does this
// belongs in the process type settings rather than here.
const isProgramLaserProcess = (name) =>
  /laser/i.test(name || "") && !/tube/i.test(name || "") && !/external/i.test(name || "");

// Two machines, two lanes. The plate laser (Nesting, Laser) and the tube
// laser (Tube Laser Nesting, Tube Laser) are different machines running
// different processes, and neither waits for the other: tube work does
// not queue behind plate nesting, and plate work does not queue behind
// the tube nester. Everything after them -- bending, welding, and so on
// -- still waits for both, because it needs the parts from both.
//
// Before this, a tube job that also carried the plate stages sat on the
// Production tab saying "Waiting on Nesting" however much the tube nester
// had done, because the flow is one straight line and the plate stages
// happened to be earlier in it. "Laser - External" is neither machine
// and stays in the main line.
const isTubeLaserProcess = (name) => /tube/i.test(name || "") && /laser|nest/i.test(name || "");
const isPlateLaserProcess = (name) => isPlateNestingProcess(name) || isProgramLaserProcess(name);
// True when a stage should not wait for another: one is in the tube lane
// and the other in the plate lane.
const inOtherLaserLane = (mine, other) =>
  (isTubeLaserProcess(mine) && isPlateLaserProcess(other)) ||
  (isPlateLaserProcess(mine) && isTubeLaserProcess(other));

// Which laser a shortage belongs to: 'plate', 'tube', or null for one
// flagged before shortages knew (setup-shortage-lane.sql). A shortage
// with no lane is shown to both nesting departments, and says so, rather
// than vanishing from both.
const shortageInLane = (shortage, processName) => {
  if (!shortage?.lane) return true;
  return isTubeLaserProcess(processName) ? shortage.lane === "tube" : shortage.lane === "plate";
};
// A stage that belongs to the OTHER laser from the shortage. Used to
// keep a tube re-cut off the plate nester's list and vice versa.
const stageInOtherLane = (shortage, processName) => {
  if (shortage?.lane === "tube") return isPlateLaserProcess(processName);
  if (shortage?.lane === "plate") return isTubeLaserProcess(processName);
  return false;
};
const laneLabel = (lane) => (lane === "tube" ? "Tube laser" : lane === "plate" ? "Plate laser" : "");

// How long a shortage has been waiting, in words, from when it was
// flagged. One day outstanding is already too long: it is work that was
// supposed to be finished.
const SHORTAGE_AGE_WARNING_DAYS = 1;
const shortageAgeDays = (shortage) => {
  const t = new Date(shortage?.created_at || 0).getTime();
  if (!t) return null;
  return Math.floor((Date.now() - t) / 86400000);
};
const shortageFlaggedLabel = (shortage) => {
  const d = new Date(shortage?.created_at || 0);
  if (!d.getTime()) return `Flagged by ${shortage?.flagged_by || "someone"} (${shortage?.flagged_department || "?"})`;
  const days = shortageAgeDays(shortage);
  const age = days === 0 ? "today" : days === 1 ? "1 day ago" : `${days} days ago`;
  const when = d.toLocaleString("en-ZA", { day: "numeric", month: "short", hour: "2-digit", minute: "2-digit" });
  return `Flagged by ${shortage.flagged_by || "someone"} (${shortage.flagged_department || "?"}) · ${age}, ${when}`;
};
const shortageIsOverdue = (shortage) => (shortageAgeDays(shortage) ?? 0) >= SHORTAGE_AGE_WARNING_DAYS;

